  var POSTS = [{"id":1,"title":"翠湖边的第七个早晨","cat":"城市观察","author":"林知","views":1280,"date":"11-18","status":1,"excerpt":"昆明的秋天从翠湖开始。六点半，海鸥还没醒，卖饵块的摊子已经支起来了。","deck":"七点前的翠湖，属于晨练的人、卖饵块的人，和一圈圈还没被游客踩乱的涟漪。","content":"昆明的秋天从翠湖开始。六点半，海鸥还没醒，卖饵块的摊子已经支起来了。我坐在长椅上，看晨练的人一圈圈走过。\n\n第七个早晨，我终于记住了他们的顺序：先是一位穿灰外套的老人，拎着收音机；然后是跑步的年轻夫妻；最后才是那群拍海鸥的人。城市在这里慢下来，慢到可以数清每一圈涟漪。"},{"id":2,"title":"把一台旧笔记本变成家庭服务器","cat":"技术手记","author":"林知","views":962,"date":"11-17","status":1,"excerpt":"2016 年的笔记本只有 8G 内存，但跑 MariaDB、Redis 和一个静态站点足够了。","deck":"八 G 内存的旧机器，怎么在不折腾的前提下，稳稳跑过三个月。","content":"这台 2016 年的笔记本只有 8G 内存，但跑 MariaDB、Redis 和一个静态站点足够了。真正难的不是安装，而是让它稳定运行三个月。\n\n我把自动更新关掉，把日志切到按周轮转，又给它接了一块移动硬盘做冷备。第三个月的最后一天，它仍然在线。"},{"id":3,"title":"在菜市场里理解供应链","cat":"城市观察","author":"周野","views":744,"date":"11-16","status":1,"excerpt":"凌晨四点的批发市场，是一天里信息最密集的地方。","deck":"在批发市场，价格、天气和到货量都写在摊主的脸上。","content":"凌晨四点的批发市场，是一天里信息最密集的地方。价格、天气、到货量、客流，全写在摊主的脸上。\n\n批发不是把货从 A 搬到 B，而是在正确的时间，把正确的量放在正确的位置。"},{"id":4,"title":"为什么我又开始用纸笔记账","cat":"生活切片","author":"林知","views":531,"date":"11-15","status":1,"excerpt":"电子表格很强大，但它不会让我停下来。","deck":"纸和笔不擅长计算，却擅长让人停一下。","content":"电子表格很强大，但它不会让我停下来。纸上写错一笔，要划掉重写，这个动作本身就在提醒我：钱花出去了。\n\n一个月后，我发现自己不再为了凑满减买不需要的东西。"},{"id":5,"title":"一个前端工程师的雨后散步","cat":"城市观察","author":"周野","views":418,"date":"11-14","status":1,"excerpt":"雨停之后，北京路的地砖反着光。","deck":"雨停后的北京路，地砖、饵块香，还有一条突然想起的小巷。","content":"雨停之后，北京路的地砖反着光。走到文明街，闻到烤饵块的甜味，突然想起小时候放学的那条巷子。\n\n代码写久了，会忘记城市本身也是一个系统：人流是请求，路口是网关，雨是突发流量。"},{"id":6,"title":"开源项目维护者的深夜清单","cat":"技术手记","author":"林知","views":356,"date":"11-13","status":0,"excerpt":"合并请求、复现步骤、版本号、发布说明。","deck":"凌晨一点，合并请求、复现步骤和发布说明，构成了维护者的夜班。","content":"合并请求、复现步骤、版本号、发布说明。凌晨一点，我把这些做完，才敢关掉编辑器。\n\n维护一个开源项目，最消耗人的不是写代码，而是反复解释为什么这样设计。"}];
